begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('91919191-9191-4191-8191-919191919191','convert-a@example.test'),('92929292-9292-4292-8292-929292929292','convert-b@example.test');
select ok(not has_function_privilege('anon','public.convert_counter_to_project(uuid,uuid,bigint,text)','EXECUTE'),'anonymous conversion denied');
select ok(not has_table_privilege('authenticated','public.counter_project_conversions','INSERT'),'receipt direct writes denied');
set local role authenticated;
set local request.jwt.claim.sub='91919191-9191-4191-8191-919191919191';
select set_config('test.conv_work',public.create_counter_work_item()->'state'->>'workItemId',true);
select is(public.apply_counter_command('91919191-0000-4000-8000-000000000001',current_setting('test.conv_work')::uuid,0,'2026-10-20T01:02:03Z','conversion-test','{"type":"setValue","counter":"stitch","value":42}')->>'status','applied','source count set');
select is(public.apply_counter_command('91919191-0000-4000-8000-000000000002',current_setting('test.conv_work')::uuid,1,'2026-10-20T01:02:04Z','conversion-test','{"type":"setTarget","counter":"stitch","value":40}')->>'status','applied','source target set');
select set_config('test.conv_complete',public.apply_counter_command('91919191-0000-4000-8000-000000000003',current_setting('test.conv_work')::uuid,2,'2026-10-20T01:02:05Z','conversion-test','{"type":"completeRow","stitch":"reset"}')::text,true);
select is(public.apply_counter_command('91919191-0000-4000-8000-000000000004',current_setting('test.conv_work')::uuid,3,'2026-10-20T01:02:06Z','conversion-test',jsonb_build_object('type','undo','eventId',current_setting('test.conv_complete')::jsonb->>'eventId'))->>'status','applied','source undo recorded');
select set_config('test.conv_counters',(select jsonb_agg(to_jsonb(c) order by counter_type)::text from public.counters c where work_item_id=current_setting('test.conv_work')::uuid),true);
select set_config('test.conv_events',(select jsonb_agg(to_jsonb(e) order by revision_after)::text from public.counter_events e where work_item_id=current_setting('test.conv_work')::uuid),true);
select is(jsonb_array_length(public.list_account_counters()),1,'source in standalone list');
select is(public.convert_counter_to_project(current_setting('test.conv_work')::uuid,'91919191-0000-4000-8000-000000000010',3,'가디건')->>'status','conflict','stale source revision blocked');
select throws_ok(format('select public.convert_counter_to_project(%L::uuid,%L::uuid,4,%L)',current_setting('test.conv_work'),'91919191-0000-4000-8000-000000000011',' '),'22023',null,'blank project name blocked');
select set_config('test.conv_result',public.convert_counter_to_project(current_setting('test.conv_work')::uuid,'91919191-0000-4000-8000-000000000012',4,'가디건')::text,true);
select is(current_setting('test.conv_result')::jsonb->>'status','converted','account counter converted');
select is(current_setting('test.conv_result')::jsonb->>'workItemId',current_setting('test.conv_work'),'same work item reused');
select is((select count(*) from public.work_items),1::bigint,'no extra work item created');
select is((select count(*) from public.counters),2::bigint,'no extra counters created');
select is((select revision from public.work_items where id=current_setting('test.conv_work')::uuid),4::bigint,'counter revision unchanged');
select is((select jsonb_agg(to_jsonb(c) order by counter_type) from public.counters c where work_item_id=current_setting('test.conv_work')::uuid),current_setting('test.conv_counters')::jsonb,'counter IDs values targets timestamps fully preserved');
select is((select jsonb_agg(to_jsonb(e) order by revision_after) from public.counter_events e where work_item_id=current_setting('test.conv_work')::uuid),current_setting('test.conv_events')::jsonb,'event IDs undo links snapshots and occurrence times fully preserved');
select is(jsonb_array_length(public.list_account_counters()),0,'converted work removed from standalone list');
select is(public.get_counter_project_link(current_setting('test.conv_work')::uuid)->>'projectId',current_setting('test.conv_result')::jsonb->>'projectId','mapping available to owner');
select is(public.convert_counter_to_project(current_setting('test.conv_work')::uuid,'91919191-0000-4000-8000-000000000012',4,'가디건')->>'status','duplicate','same request returns previous project');
select throws_ok(format('select public.convert_counter_to_project(%L::uuid,%L::uuid,4,%L)',current_setting('test.conv_work'),'91919191-0000-4000-8000-000000000013','다른 프로젝트'),'22023',null,'same work item cannot join two projects');
select throws_ok(format('select public.convert_counter_to_project(%L::uuid,%L::uuid,4,%L)',current_setting('test.conv_work'),'91919191-0000-4000-8000-000000000012','다른 이름'),'22023',null,'request ID cannot change payload');
select is((select count(*) from public.projects),1::bigint,'failures left no partial project');
set local request.jwt.claim.sub='92929292-9292-4292-8292-929292929292';
select throws_ok(format('select public.convert_counter_to_project(%L::uuid,%L::uuid,4,%L)',current_setting('test.conv_work'),'92929292-0000-4000-8000-000000000001','탈취'),'P0002',null,'other owner conversion denied');
select ok(public.get_counter_project_link(current_setting('test.conv_work')::uuid) is null,'other owner mapping hidden');
select is(jsonb_array_length(public.list_account_counters()),0,'other owner standalone list empty');
set local request.jwt.claim.sub='91919191-9191-4191-8191-919191919191';
select is(public.delete_project((current_setting('test.conv_result')::jsonb->>'projectId')::uuid,0)->>'result','deleted','converted project soft deletion works');
select is((select count(*) from public.counter_events),0::bigint,'deleted converted events hidden');
select throws_ok(format('select public.convert_counter_to_project(%L::uuid,%L::uuid,4,%L)',current_setting('test.conv_work'),'91919191-0000-4000-8000-000000000014','재전환'),'22023',null,'deleted membership cannot be bypassed by conversion');
select is(public.restore_project((current_setting('test.conv_result')::jsonb->>'projectId')::uuid,'91919191-0000-4000-8000-000000000015',1)->>'status','restored','converted project can be recovered');
select is((select count(*) from public.counter_events),4::bigint,'original converted events visible after recovery');
select * from finish();
rollback;
